import {sampledPaths} from './strokes.js';import {evaluated} from '../animation/evaluate.js';import {localBounds} from './matrix.js';import {createMesh} from './mesh.js';
export function fitMesh(n,time=0,previous){const v=evaluated(n,time),b=localBounds(n,time),paths=sampledPaths(v).filter(p=>p.closed);if(!paths.length)throw Error('Close the shape before fitting a mesh.');const area=p=>Math.abs(p.reduce((s,a,i)=>{const q=p[(i+1)%p.length];return s+a.x*q.y-q.x*a.y;},0));const ring=paths.sort((a,b)=>area(b.points)-area(a.points))[0].points;const inside=p=>{let yes=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],q=ring[j];if((a.y>p.y)!==(q.y>p.y)&&p.x<(q.x-a.x)*(p.y-a.y)/(q.y-a.y)+a.x)yes=!yes;}return yes;};let center={x:b.x+b.width/2,y:b.y+b.height/2};if(!inside(center)){let best=-1;for(let r=1;r<20;r++)for(let c=1;c<20;c++){const p={x:b.x+b.width*c/20,y:b.y+b.height*r/20};if(!inside(p))continue;const score=Math.min(...ring.map(q=>Math.hypot(q.x-p.x,q.y-p.y)));if(score>best){best=score;center=p;}}if(best<0)throw Error('This shape is too narrow for a contour mesh.');}const mesh=previous?structuredClone(previous):createMesh(b,v.fill,5,5);mesh.bounds={...b};mesh.contour=true;mesh.geometryTime=time;mesh.curved=n.type==='ellipse'||v.nodes.some(p=>p.in||p.out);
 mesh.points=mesh.points.map((p,i)=>{const u=(i%mesh.cols)/(mesh.cols-1)*2-1,v=Math.floor(i/mesh.cols)/(mesh.rows-1)*2-1,f=Math.max(Math.abs(u),Math.abs(v));if(!f)return {...p,...center};const dx=u*b.width/2,dy=v*b.height/2;let distance=Infinity;for(let j=0;j<ring.length-1;j++){const a=ring[j],q=ring[j+1],sx=q.x-a.x,sy=q.y-a.y,det=dx*sy-dy*sx;if(Math.abs(det)<1e-9)continue;const ax=a.x-center.x,ay=a.y-center.y,t=(ax*sy-ay*sx)/det,k=(ax*dy-ay*dx)/det;if(t>0&&k>=0&&k<=1)distance=Math.min(distance,t);}if(!Number.isFinite(distance))return {...p,x:center.x+dx,y:center.y+dy};return {...p,x:center.x+dx*distance*f,y:center.y+dy*distance*f};});return mesh;}
